    /**
     * 当たったフォールバック段（1..6, 7=GLOBAL）。
     */
    public var matchedStage: UInt8
    /**
     * 民明書房調の解説文（「詳説 世界の遺物」より抜粋の体裁。参照文を含みうる）。
     */
    public var description: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(width: UInt32, height: UInt32, png: Data, 
        /**
         * 選ばれたベース遺物の名称（DB由来）。
         */baseName: String, 
        /**
         * 型キー（=image_set_id, 提案01 判断D）。
         */imageSetId: Int64, 
        /**
         * 当たったフォールバック段（1..6, 7=GLOBAL）。
         */matchedStage: UInt8, 
        /**
         * 民明書房調の解説文（「詳説 世界の遺物」より抜粋の体裁。参照文を含みうる）。
         */description: String) {
        self.width = width
        self.height = height
        self.png = png
        self.baseName = baseName
        self.imageSetId = imageSetId
        self.matchedStage = matchedStage
        self.description = description
    }
}

