extension RenderedImage: Equatable, Hashable {
    public static func ==(lhs: RenderedImage, rhs: RenderedImage) -> Bool {
        if lhs.width != rhs.width {
            return false
        }
        if lhs.height != rhs.height {
            return false
        }
        if lhs.png != rhs.png {
            return false
        }
